/**
 * @type   : prototype_function
 * @access : public
 * @desc   : 엑셀 파일로 저장하거나 엑셀을 실행하여 그리드 내용을 보여준다.
 * <pre>
 * </pre>
 * @sig    : gridId, name,type
 * @param  : grid required 다운받을 그리드 아이디
 * @param  : name required sheet나 엑셀파이일명
 * @return : type 좀더 더 다양한 방법으로 다운받을 경우 처리...(확장성고려)
 */
fileType = "";
/**
 * @method
 * @name ComGridToExcel
 * @description desc
 * @param {string} gridId desc
 * @param {string} name desc
 * @param {string} type desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ComGridToExcel = async function(gridId, name, type) {
    var szPath = "C:\\"; //파일저장 디폴트 경로
    var oDataSet = document.all(gridId.DataId);

    //데이터가 없는경우 조회후 검색하세요 메세지 처리.
    if (oDataSet.getTotalRow() <= 0) {
        alert("데이터가 없습니다. 조회후 다운받아주세요.");
        return;
    }
    vXpos = 500;
    vYpos = 300;
    await $c.frame.CreateDialogFrame("virWinOpen", "/osm/iui/ui/excelDown.gfm", "엑셀다운로드", vXpos, vYpos, 250, 100, "tool");
    if (scwin.fileType != "") {
        if (scwin.fileType == "1") {
            //엑셀로 받기
            if (type == "1") {
                gridId.GridToExcel(name, szPath + name, 29); //show false인것은 안보여준다.

            } else {
                gridId.GridToExcel(name, szPath + name, 31);
            }
        } else if (scwin.fileType == "2") {
            //파일로 받기
            if (type == "2") {
                gridId.GridToExcel(name, " ", 31); //show false인것은 안보여준다.
                alert("파일1");
            } else {
                alert("파일2");
                gridId.GridToExcel(name, " ", 31);
            }
        }
    }
};





/******************************************************************* 
 * 함수명   : InfoMenuID()
 * 설명     : MenuID를 갖다준다
 * argument : 
 *******************************************************************/
/**
 * @method
 * @name InfoMenuID
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.InfoMenuID = function() {
    var e = $c.frame.path("/pageIndex").selPageID;
    e = e.split("_");
    var myStr = e[1];
    return myStr;
};
/**
 * @method
 * @name fn_OpenDisclViewer_MGT
 * @description desc
 * @param {string} pAcptNo desc
 * @param {string} vScrenID desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenDisclViewer_MGT = async function(pAcptNo, vScrenID) {
    var vHttp;
    if (js_svrGubun.indexOf('dev') > -1) {
        vHttp = scwin.g_dev_stf_url;
    } else if (js_svrGubun.indexOf("test") > -1) {
        vHttp = scwin.g_test_stf_url;
    } else {
        vHttp = scwin.real_stf_url;
    }
    var url = vHttp + "/dsclproc/ULDSTF10001.gfm?" + "gAcptNo=" + pAcptNo + "&gViewerStat=R" + "&frameID=" + frame.FrameID + "&gAccssAuthTpCd=01" + "&screnID=" + vScrenID;
    var winTitle = "공시뷰어";
    if ($c.frame.path("/top") != undefined) {
        $c.frame.path("/top").WinOpen_child("viewer" + pAcptNo, url, winTitle, 1000, 800);
    } else {
        await $c.frame.CreateFrame("viewer" + pAcptNo, url, winTitle, 10, 10, 1000, 800, "window", 0, 0, true);
    }
};



