 */
scwin._trk_adClick = function(adSvr, svcCode, adCode) {
    var ac = "";
    var prtcl = document.location.protocol.indexOf("https") != -1 ? "https://" : "http://"; /* Solution Setting - if(prtcl=="https://") adSvr="ssl."+_TRK_DOMAIN; */
